template <>
struct Codec<LedgerKey> {
  static constexpr std::uint64_t kMinSize = 4;
  static bool encode(const LedgerKey&, Encoder&);
  static bool decode(LedgerKey&, Decoder&);
  static bool gen(LedgerKey&, XdrRng&, std::uint32_t);
  template <typename F>
  static void visit_fields(const LedgerKey& v, F&& f) {
    f("type", v.t_);
    switch (v.t_) {
      case LedgerEntryType::ACCOUNT:
        f("account", std::get<0>(v.v_));
        return;
      case LedgerEntryType::TRUSTLINE:
        f("trustLine", std::get<1>(v.v_));
        return;
      case LedgerEntryType::OFFER:
        f("offer", std::get<2>(v.v_));
        return;
      case LedgerEntryType::DATA:
        f("data", std::get<3>(v.v_));
        return;
      case LedgerEntryType::CLAIMABLE_BALANCE:
        f("claimableBalance", std::get<4>(v.v_));
        return;
      case LedgerEntryType::LIQUIDITY_POOL:
        f("liquidityPool", std::get<5>(v.v_));
        return;
      case LedgerEntryType::CONTRACT_DATA:
        f("contractData", std::get<6>(v.v_));
        return;
      case LedgerEntryType::CONTRACT_CODE:
        f("contractCode", std::get<7>(v.v_));
        return;
      case LedgerEntryType::CONFIG_SETTING:
        f("configSetting", std::get<8>(v.v_));
        return;
      case LedgerEntryType::TTL:
        f("ttl", std::get<9>(v.v_));
        return;
      default: return;
    }
  }
};
